'use strict';
const KEY='daily-reps-engine-v2';
const clone=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const newProfile=name=>({id:crypto.randomUUID(),name,onboardingComplete:false,experience:'beginner',kettlebellCount:1,dumbbellCount:2,equipment:['Bodyweight'],bans:[],mode:'rotation',weeklyTarget:3,rotationIndex:0,schedule:['Push','Pull','Lower'].map(type=>({type,custom:null})),history:[],session:null});
let state=readStoredState();if(!state){const p=newProfile('My profile');state={profiles:[p],active:p.id};}
let tab='Workout',day=(new Date().getDay()+6)%7,openAlts=new Set(),previewSwaps={},audioCtx=null,storageWarning=false,setupDraft=null,focusMode=false;
const profile=()=>state.profiles.find(x=>x.id===state.active);
function persist(){if(!saveState(state)&&!storageWarning){storageWarning=true;toast('Storage unavailable. Export a backup in Settings.');}}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>t.style.display='none',4000);}
function norm(s){return s.toLowerCase().replace(/\bdb\b/g,'dumbbell').replace(/\bkb\b/g,'kettlebell').replace(/[^a-z0-9]+/g,' ').trim();}
function allowed(m,p=profile()){m=reviewedMovement(m);return m&&m.equipment.every(x=>x==='Bodyweight'||normalizeEquipment(p.equipment).includes(x))&&requiredKettlebells(m)<=(p.kettlebellCount||1)&&requiredDumbbells(m)<=(p.dumbbellCount||2)&&!p.bans.some(b=>norm(m.name+' '+(MUSCLE_GROUPS[m.group]||'')+' '+(m.pattern||'')).includes(norm(b).replace(/^no /,'')));}
function circuit(d=day,p=profile()){const plan=p.schedule[d];if(plan.type==='Rest')return [];const used=new Set();return PRESETS[plan.type].map((ids,i)=>{const custom=plan.custom?.[i];let candidates=custom?[custom.main,custom.alt].filter(Boolean):ids.map(id=>MOVES[id]);if(!custom&&p.experience){const group=MOVES[ids[0]].group;const target={beginner:1,intermediate:3,advanced:4}[p.experience]||3;candidates=[...candidates,...Object.values(MOVES).filter(m=>m.group===group&&!m.libraryAlias)].map(reviewedMovement);const preferred=new Set(ids.map(id=>MOVES[id].pattern)),cap=p.experience==='beginner'?2:p.experience==='intermediate'?3:5;if(candidates.some(m=>allowed(m,p)&&!used.has(m.name)&&(m.challenge||2)<=cap))candidates=candidates.filter(m=>(m.challenge||2)<=cap);candidates.sort((a,b)=>Number(!preferred.has(a.pattern))-Number(!preferred.has(b.pattern))||Math.abs((a.challenge||2)-target)-Math.abs((b.challenge||2)-target));}if(!custom)candidates=candidates.filter(m=>m?.group===MOVES[ids[0]].group);let main=candidates.find(m=>allowed(m,p)&&!used.has(m.name));if(!main&&!custom){const group=MOVES[ids[0]].group;main=Object.values(MOVES).find(m=>m.group===group&&allowed(m,p)&&!used.has(m.name));}if(main)used.add(main.name);const alt=candidates.find(m=>allowed(m,p)&&m.name!==main?.name)||(!custom?Object.values(MOVES).find(m=>allowed(m,p)&&m.group===main?.group&&m.name!==main?.name):null);return {main:main?clone(reviewedMovement(main)):null,alt:alt?clone(reviewedMovement(alt)):null};});}
function activeSession(){return profile().session;}
function hasActive(){const s=activeSession();return s&&!s.finished;}
function currentCircuit(){const s=activeSession();if(s&&s.day===day&&!s.finished)return s.circuit;const override=profile().workoutOverrides;const rows=override?.date===localDate()&&override.slots?.[day]?clone(override.slots[day]):circuit();for(const r of rows)if(r.main)r.main.weightKg=savedLoad(r.main);return rows;}
function movePattern(m){const known=Object.values(MOVES).find(x=>x.name===m?.name);return m?.pattern||known?.pattern||m?.group||known?.group||null;}
function moveGroup(m){return m?.group||Object.values(MOVES).find(x=>x.name===m?.name)?.group||null;}
function swapRelation(main,alt){return movePattern(main)&&movePattern(main)===movePattern(alt)?'Similar movement pattern':'Different movement · different stimulus';}
function alternativesFor(r,i,rows=currentCircuit()){
 const group=moveGroup(r.main)||MOVES[PRESETS[profile().schedule[day].type]?.[i]?.[0]]?.group;
 const explicit=[...(r.alts||[]),r.alt].filter(Boolean),candidates=[...explicit,...Object.values(MOVES).filter(m=>m.group===group&&!m.libraryAlias)].map(reviewedMovement);
 const occupied=new Set(rows.filter((_,n)=>n!==i).map(r=>r.main?.name)),names=new Set([r.main?.name]);
 return candidates.filter(m=>{if(!allowed(m)||names.has(m.name)||occupied.has(m.name)||moveGroup(m)!==group)return false;names.add(m.name);return true;}).sort((a,b)=>Number(movePattern(b)===movePattern(r.main))-Number(movePattern(a)===movePattern(r.main)));
}
function swapExercise(i,choice){const s=activeSession();if(s&&!s.finished&&s.day!==day)return;if(s?.running&&remaining(s)<=0)enterOvertime(s);const rows=currentCircuit(),r=rows[i];if(!r)return;const choices=alternativesFor(r,i,rows),replacement=choices[choice];if(!replacement)return;const old=clone(r.main);r.main=clone(replacement);r.main.weightKg=savedLoad(r.main);r.alt=old;r.alts=old?[old]:[];if(s&&!s.finished){s.circuit=rows;s.echoInvalid=true;}else{const p=profile();if(p.workoutOverrides?.date!==localDate())p.workoutOverrides={date:localDate(),slots:{}};p.workoutOverrides.slots[day]=clone(rows);}persist();render();toast('Movement swapped for this workout.');}
function remaining(s=activeSession()){return !s?1200000:s.overtime?0:s.running?Math.max(0,s.endAt-Date.now()):s.remaining;}
function workoutElapsed(s=activeSession()){
 if(!s)return 0;if(s.finished)return s.durationMs||1200000;
 return s.running?Math.max(0,1200000+Date.now()-s.endAt):s.overtime?1200000+(s.overtimeMs||0):1200000-s.remaining;
}
function clockText(ms){const sec=Math.floor(Math.max(0,ms)/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function durationCaption(h){const extra=h.overtimeMs??Math.max(0,(h.durationMs||1200000)-1200000);return extra>0?`20 min + ${clockText(extra)} overtime`:'20 min';}
function enterOvertime(s){
 if(!s||s.finished||s.overtime)return;s.overtime=true;s.remaining=0;s.overtimeMs=Math.max(0,workoutElapsed(s)-1200000);
 const notify=!s.milestoneNotified;s.milestoneNotified=true;persist();if(notify)playFinishTune();
 render();syncWakeLock();toast('20-minute target reached. Log your last reps, then finish & save.');
}
function overtimePanel(s){return s?.overtime&&!s.finished?`<section class="overtime-banner" role="status"><div><strong>20-minute target reached · Overtime</strong><p>Finish your last set and log any remaining reps. Your session stays open until you save.</p></div><button class="primary" data-action="finish-workout">Finish & save</button></section>`:'';}

function streak(){const dates=new Set(profile().history.map(h=>h.date));let d=new Date();d.setHours(12,0,0,0);if(!dates.has(localDate(d)))d.setDate(d.getDate()-1);let n=0;while(dates.has(localDate(d))){n++;d.setDate(d.getDate()-1);}return n;}
function options(items,value){return items.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');}
function unitFor(m){return /^\s*[\d–—. -]+\s*(sec|seconds|s)(?:\s*\/\s*side)?\s*$/i.test(m?.reps||'')?'sec':'reps';}
function repEntries(s){return s?.repEntries||[];}
function countTotal(entries,unit='reps'){return entries.filter(e=>e.unit===unit).reduce((sum,e)=>sum+e.count,0);}
function savedLoad(m){const key='move:'+m?.name,loads=profile().loads||{};if(Object.prototype.hasOwnProperty.call(loads,key))return loads[key];if(m?.weightKg!=null)return m.weightKg;const previous=profile().history.slice().reverse().flatMap(h=>h.repEntries||[]).find(e=>e.name===m?.name);return previous?previous.weightKg??null:m?.equipment?.every(e=>['Bodyweight','Stable Bench / Support','Step / Platform','Ab Wheel'].includes(e))?0:null;}

function sameEntry(a,b){return a.name===b.name&&a.unit===b.unit&&(a.weightKg??null)===(b.weightKg??null);}
function sessionEntries(s){const entries=clone(repEntries(s));for(const r of s.circuit){const m=r.main,row={name:m?.name,unit:unitFor(m),weightKg:m?.weightKg??null,count:0};if(m&&!entries.some(e=>sameEntry(e,row)))entries.push(row);}return entries;}
function weightUnit(){return profile().preferences?.weightUnit==='lb'?'lb':'kg';}
function displayWeight(kg){return Math.round(kg*(weightUnit()==='lb'?2.2046226218487757:1)*100)/100;}
function loadCaption(e){return e.weightKg==null?'Load not recorded':e.weightKg===0?'No external load':`${displayWeight(e.weightKg)} ${weightUnit()} total external load`;}
function weightUnitSettings(){return `<section class="section"><h2>Weight units</h2><label for="weight-unit">Display and enter weights in</label><select id="weight-unit"><option value="kg" ${weightUnit()==='kg'?'selected':''}>Kilograms (kg)</option><option value="lb" ${weightUnit()==='lb'?'selected':''}>Pounds (lb)</option></select><p class="small muted">Existing weights are converted for display. Your saved training data stays unchanged.</p></section>`;}
function loadField(m,i,s){const stored=m?.weightKg??savedLoad(m);return m?`<label class="load-field" for="load-${i}">Total external load (${weightUnit()}) <input id="load-${i}" data-load="${i}" inputmode="decimal" type="text" maxlength="16" placeholder="Optional" value="${esc(stored==null?'':displayWeight(stored))}"></label><p class="small muted load-help">Two weights: add both together. One weight: enter that weight. Bodyweight: 0. Bands: leave blank.</p>`:'';}
function saveDisplayLoad(i,raw){
 const text=raw.trim().replace(',','.');if(text===''){saveLoad(i,'');return;}
 if(!/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(text)){toast('Enter a positive weight or leave the field blank.');render();return;}
 const shown=Number(text),m=currentCircuit()[i]?.main;if(!m)return;const previous=m.weightKg??savedLoad(m);
 const kg=previous!=null&&shown===displayWeight(previous)?previous:shown/(weightUnit()==='lb'?2.2046226218487757:1);
 if(!Number.isFinite(kg)||kg>1000){toast(`Enter a weight up to ${displayWeight(1000)} ${weightUnit()}, or leave it blank.`);render();return;}
 saveLoad(i,String(kg));
}

function saveLoad(i,raw){const rows=currentCircuit(),m=rows[i]?.main;if(!m)return;const weight=raw.trim()===''?null:Number(raw);if(weight!==null&&(!Number.isFinite(weight)||weight<0||weight>1000)){toast('Enter a load between 0 and 1000 kg, or leave it blank.');render();return;}profile().loads??={};const session=activeSession();if(session&&!session.finished&&session.day===day){if(session.running&&remaining(session)<=0)enterOvertime(session);if((m.weightKg??null)!==weight){m.weightKg=weight;session.echoInvalid=true;}}profile().loads['move:'+m.name]=weight;persist();}
function groupedBreakdown(entries){
 const groups=new Map();
 for(const entry of entries){
  let group=groups.get(entry.name);if(!group){group={name:entry.name,reps:0,seconds:0,loads:new Map()};groups.set(entry.name,group);}
  if(entry.unit==='sec')group.seconds+=entry.count;else group.reps+=entry.count;
  const key=JSON.stringify([entry.unit,entry.weightKg??null]),row=group.loads.get(key);
  if(row)row.count+=entry.count;else group.loads.set(key,{...entry});
 }
 return [...groups.values()].map(group=>({...group,hasReps:[...group.loads.values()].some(e=>e.unit==='reps'),hasSeconds:[...group.loads.values()].some(e=>e.unit==='sec'),loads:[...group.loads.values()]}));
}
function breakdown(entries){return `<div class="rep-breakdown">${groupedBreakdown(entries).map(group=>`<section class="exercise-result"><div class="result-group-title"><h3>${esc(group.name)}</h3><strong>${group.hasReps?`${group.reps.toLocaleString()} <small>reps</small>`:''}${group.hasReps&&group.hasSeconds?' · ':''}${group.hasSeconds?`${group.seconds.toLocaleString()} <small>sec</small>`:''}</strong></div><ul class="result-loads">${group.loads.map(e=>`<li class="result-load-line"><span>${esc(loadCaption(e))}</span><strong>${e.count.toLocaleString()} <small>${e.unit}</small></strong></li>`).join('')}</ul></section>`).join('')}</div>`;}

function addReps(i,amount){const s=activeSession();if(!s||s.finished||s.day!==day||(!Number.isInteger(amount)||amount<1||amount>1000))return;if(s.running&&remaining(s)<=0)enterOvertime(s);const m=s.circuit[i]?.main;if(!m)return;s.repEntries??=[];s.repLog??=[];const unit=unitFor(m);const row={name:m.name,unit,weightKg:m.weightKg??null};let entry=s.repEntries.find(e=>sameEntry(e,row));if(!entry){entry={...row,count:0};s.repEntries.push(entry);}entry.count+=amount;s.repLog.push({name:m.name,unit,weightKg:m.weightKg??null,amount,slot:i,at:workoutElapsed(s)});persist();render();}
function undoReps(i){const s=activeSession();if(!s||s.finished||s.day!==day)return;if(s.running&&remaining(s)<=0)enterOvertime(s);const index=s.repLog?.findLastIndex(e=>e.slot===i)??-1;if(index<0)return;const [last]=s.repLog.splice(index,1);const entry=s.repEntries.find(e=>sameEntry(e,last));entry.count=Math.max(0,entry.count-last.amount);persist();render();}
function allRepEntries(){const totals=new Map();for(const h of profile().history)for(const e of h.repEntries||[]){const key=JSON.stringify([e.name,e.unit,e.weightKg??null]);const row=totals.get(key)||{...e,count:0};row.count+=e.count;totals.set(key,row);}return [...totals.values()].sort((a,b)=>b.count-a.count);}
function repOverview(){const entries=allRepEntries(),tracked=profile().history.filter(h=>Array.isArray(h.repEntries)).length;return `<section class="section" style="margin-top:24px"><div class="eyebrow">ALL COMPLETED SESSIONS</div><h2 style="margin-top:8px">${countTotal(entries).toLocaleString()} total reps</h2>${countTotal(entries,'sec')?`<p>${countTotal(entries,'sec')} seconds of holds, tracked separately</p>`:''}<p class="small">${tracked} sessions with rep tracking. Earlier sessions have no rep counts.</p>${entries.length?breakdown(entries):'<p style="margin-top:16px">Log reps during your next workout to build your exercise overview.</p>'}</section>`;}
function metrics(){const n=profile().history.length;return `<div class="metric-row"><div class="metric"><strong>${n}</strong><span>Sessions completed</span></div><div class="metric"><strong>${Math.round(profile().history.reduce((n,h)=>n+(h.durationMs||1200000),0)/60000)}<small style="font-size:14px"> min</small></strong><span>Training time</span></div><div class="metric"><strong>${weeklyCompleted()}<small style="font-size:14px"> / ${weeklyTarget()}</small></strong><span>Weekly goal</span></div></div>`;}
function week(){const p=profile();if(isRotation()){const next=nextWorkoutIndex();return `<section class="rotation-summary"><div><div class="eyebrow">${hasActive()?'CURRENT WORKOUT':'NEXT WORKOUT'}</div><h2>${esc(p.schedule[hasActive()?activeSession().day:next].type)}</h2><p class="small muted">Rolling rotation · ${weeklyTarget()} sessions per week</p></div>${day!==next&&!hasActive()?'<button data-action="next-workout">Open next workout</button>':''}</section><div class="rotation-queue" aria-label="Workout sequence">${p.schedule.map((_,offset)=>{const i=(next+offset)%p.schedule.length;return `<button class="queue-item ${day===i?'selected':''}" data-action="day" data-i="${i}" aria-pressed="${day===i}"><span>${offset===0?'Next':`Then ${offset+1}`}</span><strong>${esc(p.schedule[i].type)}</strong></button>`;}).join('')}</div>${monthCalendar()}`;}return `<div class="week" aria-label="Select workout day">${p.schedule.map((plan,i)=>`<button class="day ${day===i?'selected':''}" data-action="day" data-i="${i}" aria-pressed="${day===i}"><span>${DAYS[i].slice(0,3)}</span><strong>${esc(plan.type)}</strong></button>`).join('')}</div>${monthCalendar()}`;}
function uiIcon(name){const paths={Workout:'<path d="M6 4v16M3 7v10M18 4v16M21 7v10M6 12h12"/>',Builder:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="9" cy="18" r="2"/>',Progress:'<path d="M4 4v16h16M8 15l4-5 4 2 4-6"/>',Settings:'<path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M5.6 18.4l2.1-2.1M16.3 7.7l2.1-2.1"/><circle cx="12" cy="12" r="5"/>',focus:'<path d="M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 11h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};return `<svg class="ui-icon" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.Workout}</svg>`;}
function render(){ensureScheduleMode();const p=profile();if(!p.schedule[day])day=defaultWorkoutIndex();document.querySelector('#app').innerHTML=`<header><div class="logo" aria-hidden="true">20</div><div class="brand">Daily Reps<small>20-minute workouts</small></div><button class="setup-button" data-action="setup">${uiIcon('Settings')}<span>Setup</span></button></header><main class="shell ${focusMode&&tab==='Workout'?'focus-mode':''}"><nav aria-label="Main navigation">${['Workout','Progress','Settings'].map(t=>`<button data-action="tab" data-tab="${t}" class="${tab===t?'active':''}" aria-current="${tab===t?'page':'false'}">${uiIcon(t)}<span>${t}</span></button>`).join('')}</nav>${storageWarning?'<div class="storage-alert">Local storage is unavailable. Export a backup from Settings before closing this page.</div>':''}${tab==='Workout'?workout():tab==='Progress'?progress():tab==='Setup'?setupView():settings()}<div id="app-update-notice" class="update-notice" hidden></div><footer><span id="runtime-status">${esc(runtimeStatus())}</span><span>Saved on this browser · <button class="text-button" data-action="export-backup">Back up data</button> · <button class="text-button" data-action="about-app">About & data</button></span></footer></main>`;tick();paintRuntimeStatus();}
function pOptions(){return state.profiles.map(p=>`<option value="${esc(p.id)}" ${p.id===state.active?'selected':''}>${esc(p.name)}</option>`).join('');}
function workout(){
 const p=profile(),plan=p.schedule[day],s=activeSession(),here=s&&s.day===day&&!s.finished,other=hasActive()&&!here,rows=currentCircuit();
 if(here&&focusMode)return trainingView(s,rows);
 const blocked=rows.some(r=>!r.main),preview=isRotation()&&day!==nextWorkoutIndex()&&!here;
 return `<section class="workout-home"><div class="home-heading"><div><span class="eyebrow">${here?'YOUR SESSION':'READY WHEN YOU ARE'}</span><h1>${esc(plan.type==='Rest'?'Recovery day':plan.type+' workout')}</h1><p class="small muted">${plan.type==='Rest'?'Recharge for your next session':`20 min · 5 exercises · ${esc(FOCUS[plan.type])}`}</p></div><button class="text-button" data-action="setup" ${hasActive()?'disabled':''}>Edit plan</button></div><div class="week-inline">${weeklyCompleted()} / ${weeklyTarget()} sessions this week <span>· ${isRotation()?'Rolling plan':DAYS[day]}</span></div>${other?`<div class="alert">A ${esc(s.type)} session is in progress. <button data-action="resume-view">Resume session</button></div>`:''}${preview?'<div class="alert">Previewing a later workout. <button data-action="next-workout">Back to next workout</button></div>':''}${plan.type==='Rest'?'<div class="section"><h2>Rest is part of the plan.</h2><p>Your next training day follows your saved schedule.</p><button data-action="setup">Adjust my days</button></div>':`<div class="home-summary"><span class="challenge-badge">${workoutChallenge(rows)}</span><button class="text-button" data-action="challenge-info">About levels</button></div><ol class="workout-compact-list">${rows.map((row,i)=>`<li><button class="compact-exercise" data-action="alt" data-i="${i}"><span class="compact-index">${i+1}</span><span class="compact-copy"><strong>${esc(row.main?.name||'Choose an available exercise')}</strong><small>${esc(row.main?groupLabel(row.main):MUSCLE_GROUPS[slotGroup(i,row)])} · ${esc(row.main?.reps||'Adjust equipment')}</small></span><span class="compact-level">${row.main?challengeBadge(row.main):'Choose'}<small>Change ›</small></span></button></li>`).join('')}</ol>${blocked?'<p class="alert">Your filters leave an empty slot. Choose an available exercise or adjust your equipment before starting.</p>':''}<div class="home-start"><div class="mini-timer"><strong id="timer" role="timer" aria-label="Time remaining">20:00</strong><span id="timer-status" class="small muted">Not started</span></div><button class="primary" id="start-btn" data-action="start" ${blocked||other||preview?'disabled':''}>${here?(s.running?'Pause':'Resume'):'Start workout'}</button>${here?'<button data-action="focus">Training view</button>':''}${overtimePanel(here?s:null)}<div class="timer-dial" hidden></div><div class="progress" role="progressbar" aria-label="Session progress" aria-valuemin="0" aria-valuemax="1200" aria-valuenow="0"><i id="timer-bar"></i></div></div><p class="home-help small muted">One set per exercise, in order. Repeat at your own pace; rest when needed.</p>`}${plan.type!=='Rest'?'<button class="workout-guide-button" data-action="workout-guide">How this workout works →</button>':''}<details class="plan-drawer"><summary>Workout schedule</summary><div class="chips">${p.schedule.map((d,i)=>`<button data-action="day" data-i="${i}" class="chip ${i===day?'selected':''}" aria-pressed="${i===day}">${isRotation()?i+1:DAYS[i].slice(0,3)} · ${esc(d.type)}</button>`).join('')}</div>${canReorderWorkouts()?`<button data-action="edit-order" ${hasActive()?'disabled':''}>Change workout order</button>`:''}</details></section>`;
}
function weeklyCompleted(){const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()-(date.getDay()+6)%7);const from=localDate(date);date.setDate(date.getDate()+7);const to=localDate(date);return profile().history.filter(h=>h.date>=from&&h.date<to).length;}

function groupLabel(m){return MUSCLE_GROUPS[moveGroup(m)]||'Custom movement';}
function slotGroup(i,r){return moveGroup(r.main)||MOVES[PRESETS[profile().schedule[day].type]?.[i]?.[0]]?.group;}
function libraryForGroup(group){return Object.values(MOVES).filter(m=>m.group===group&&!m.libraryAlias);}
function workoutGroups(){return [...new Set((PRESETS[profile().schedule[day].type]||[]).map(ids=>MOVES[ids[0]].group))];}
function exercise(r,i,s){
 const m=reviewedMovement(r.main),unit=unitFor(m),count=repEntries(s).filter(e=>e.name===m?.name&&e.unit===unit).reduce((n,e)=>n+e.count,0),last=previousSet(m,s);
 return `<article class="exercise"><div class="exercise-main"><span class="number">${i+1}</span><div class="exercise-copy"><span class="muscle-label">${esc(groupLabel(m))}</span><h3>${esc(m?.name||'Choose an exercise')}</h3><p class="small muted">${esc(m?.reps)} · ${challengeBadge(m)}</p><p class="counting-help">${esc(countingHint(m))}</p></div><div class="rep-count" aria-live="polite"><strong>${count}</strong><span>${unit}</span></div></div>${loadField(m,i,s)}<div class="rep-controls">${[1,5,10].map(n=>`<button data-action="add-reps" data-i="${i}" data-amount="${n}" aria-label="Add ${n} ${unit}" ${!s||!m?'disabled':''}>+${n}${unit==='sec'?'s':''}</button>`).join('')}<button class="undo-reps" data-action="undo-reps" data-i="${i}" ${!s?.repLog?.some(e=>e.slot===i)?'disabled':''}>Undo</button></div>${last?`<button class="repeat-set" data-action="repeat-set" data-i="${i}" ${!s?'disabled':''}>Repeat last set · ${last.amount} ${unit} · ${esc(loadCaption(last))}</button>`:''}<button class="alt-toggle" data-action="alt" data-i="${i}">Form & change exercise</button></article>`;
}
function previousSet(m,s=activeSession()){
 if(!m)return null;const match=e=>e.name===m.name&&e.unit===unitFor(m)&&Number.isInteger(e.amount)&&e.amount>0&&e.amount<=1000;
 return (s?.repLog||[]).findLast(match)||profile().history.slice().reverse().flatMap(h=>(h.repLog||[]).slice().reverse()).find(match)||null;
}

function builder(){const plan=profile().schedule[day],rows=circuit();return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:10px">PLAN YOUR WEEK</div><h1>Edit workouts</h1><p class="muted">Edit your workout circuits. Setup controls the schedule and sequence.</p></div></div>${week()}${hasActive()?'<div class="alert">Pause and reset your active session before changing workouts or equipment.</div>':''}<form id="builder-form"><fieldset ${hasActive()?'disabled':''} style="border:0;padding:0;margin:0"><div class="section"><div class="form-grid"><div><label for="routine-type">${isRotation()?`Workout ${day+1}`:DAYS[day]} routine</label><select id="routine-type">${options(isRotation()?TYPES.filter(t=>t!=='Rest'):TYPES,plan.type)}</select></div><div><label>Circuit size</label><div style="padding:11px 0">${plan.type==='Rest'?'Recovery day · no exercises':'5 exercises · 20 minutes'}</div></div></div>${plan.type==='Rest'?'<p style="margin-top:18px">This day is set aside for recovery.</p>':rows.map((r,i)=>builderRow(r,i)).join('')}</div>${plan.type!=='Rest'?'<div class="builder-actions"><button type="button" data-action="restore">Restore preset</button><button type="submit" class="primary">Save five-exercise circuit</button></div>':''}</fieldset></form>`;}
function builderRow(r,i){const main=r.main||{name:'',reps:'10–12 reps',description:'',equipment:['Bodyweight']},alt=r.alt||{name:'',equipment:['Bodyweight']};const groups=workoutGroups();const all=Object.values(MOVES).filter(m=>allowed(m)&&groups.includes(m.group)&&!m.libraryAlias);return `<div class="builder-row"><div class="number">0${i+1}</div><div><label for="library-${i}">Choose a movement for this workout, or enter your own below</label><select id="library-${i}" data-library="${i}"><option value="">Custom / current movement</option>${groups.map(g=>`<optgroup label="${esc(MUSCLE_GROUPS[g])}">${all.filter(m=>m.group===g).map(m=>`<option value="${m.id}">${esc(m.name)} · ${esc(m.pattern)}</option>`).join('')}</optgroup>`).join('')}</select><div class="form-grid"><div class="field"><label for="name-${i}">Exercise name</label><input id="name-${i}" name="name-${i}" value="${esc(main.name)}" required maxlength="100"></div><div class="field"><label for="reps-${i}">Reps / duration</label><input id="reps-${i}" name="reps-${i}" value="${esc(main.reps)}" required maxlength="60"></div></div><div class="field"><label for="group-${i}">Muscle group</label><select id="group-${i}" name="group-${i}">${groups.map(g=>`<option value="${g}" ${g===(moveGroup(main)||slotGroup(i,r))?'selected':''}>${esc(MUSCLE_GROUPS[g])}</option>`).join('')}</select></div><div class="field"><label for="desc-${i}">Form cues</label><textarea id="desc-${i}" name="desc-${i}" maxlength="500">${esc(main.description)}</textarea></div><div class="field"><label for="eq-${i}">Required equipment (select all that apply)</label><select multiple id="eq-${i}" name="eq-${i}" size="3">${EQUIPMENT.map(e=>`<option ${main.equipment.includes(e)?'selected':''}>${e}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="alt-${i}">Alternative name (optional)</label><input id="alt-${i}" name="alt-${i}" value="${esc(alt.name)}" maxlength="100"></div><div class="field"><label for="alteq-${i}">Alternative equipment</label><select multiple id="alteq-${i}" name="alteq-${i}" size="3">${EQUIPMENT.map(e=>`<option ${alt.equipment.includes(e)?'selected':''}>${e}</option>`).join('')}</select></div></div><div class="form-grid"><div class="field"><label for="altreps-${i}">Alternative reps</label><input id="altreps-${i}" name="altreps-${i}" value="${esc(alt.reps||'10–12 reps')}" maxlength="60"></div><div class="field"><label for="altdesc-${i}">Alternative form cues</label><input id="altdesc-${i}" name="altdesc-${i}" value="${esc(alt.description||'')}" maxlength="500"></div></div></div></div>`;}
function progress(){const p=profile(),dates=new Set(p.history.map(h=>h.date));const days=Array.from({length:28},(_,i)=>{let d=new Date();d.setDate(d.getDate()-27+i);return localDate(d);});return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:10px">WORKOUT HISTORY</div><h1>Progress</h1><p class="muted">Completed workouts, reps and training time.</p></div></div>${weekGoal()}${monthCalendar()}${metrics()}${repOverview()}<div class="section" style="margin-top:24px"><h2>Your last 28 days</h2><div class="dots">${days.map(d=>`<div class="dot ${dates.has(d)?'trained':''}" title="${d}: ${dates.has(d)?'Trained':'No session'}" role="img" aria-label="${d}: ${dates.has(d)?'Trained':'No session'}"></div>`).join('')}</div><p class="small">Blue = saved workout. Rest days are part of your plan; aim for your chosen weekly goal.</p></div><div class="section"><h2>Session history</h2>${p.history.length?p.history.slice().reverse().map(h=>`<div class="history"><div><strong>${esc(h.type)} circuit</strong><div class="small muted">${new Date(h.finishedAt).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}</div></div><div style="text-align:right"><strong style="color:var(--lime)">${durationCaption(h)} ✓</strong><div class="small muted">${Array.isArray(h.repEntries)?`${countTotal(h.repEntries)} reps${countTotal(h.repEntries,'sec')?` · ${countTotal(h.repEntries,'sec')} sec`: ''}`:'Reps not recorded'}</div></div></div>${Array.isArray(h.repEntries)?`<details class="history-details"><summary>Reps per exercise</summary>${breakdown(h.repEntries)}</details>`:''}`).join(''):'<div class="empty" style="border:0;padding:36px 12px"><h3>No completed workouts yet.</h3><p>Completed 20-minute workouts appear here.</p><button class="primary" data-action="tab" data-tab="Workout">Go to workout</button></div>'}</div>`;}
function settings(){const p=profile();return `<div class="heading"><div><div class="eyebrow" style="margin-bottom:10px">PREFERENCES</div><h1>Settings</h1><p class="muted">Every preset and alternative follows these filters.</p></div></div><div class="wide">${hasActive()?'<div class="alert">Reset the current session to change equipment or excluded movements.</div>':''}<section class="section"><h2>Available equipment</h2>${p.equipment.includes('Dumbbells')?dumbbellQuantityControls(p.dumbbellCount||2,'settings'):''}${p.equipment.includes('Kettlebells')?kettlebellQuantityControls(p.kettlebellCount||1,'settings'):''}<p class="small">Bodyweight exercises are always available. Select only the additional equipment you can use.</p><div class="chips">${EQUIPMENT.map(e=>`<button class="chip ${e==='Bodyweight'||p.equipment.includes(e)?'selected':''}" data-action="equipment" data-value="${e}" aria-pressed="${e==='Bodyweight'||p.equipment.includes(e)}" ${e==='Bodyweight'||hasActive()?'disabled':''}>${e==='Bodyweight'||p.equipment.includes(e)?'✓ ': '+ '}${e}${e==='Bodyweight'?' · always available':''}</button>`).join('')}</div></section><section class="section"><h2>Excluded movements</h2><p class="small">Optional: exclude an exercise name, muscle group or movement pattern. Suggestions are not excluded unless you select them.</p><div class="chips">${EXCLUSION_SUGGESTIONS.map(b=>`<button class="chip ${p.bans.includes(b)?'selected':''}" data-action="ban" data-value="${b}" ${hasActive()?'disabled':''}>${p.bans.includes(b)?'✓ ': '+ '}${b}</button>`).join('')}</div><form id="ban-form" style="display:flex;gap:8px;margin-top:16px"><input aria-label="Movement to exclude" name="ban" placeholder="e.g. overhead press" required maxlength="80" ${hasActive()?'disabled':''}><button ${hasActive()?'disabled':''}>Exclude</button></form><div class="chips">${p.bans.map(b=>`<button class="chip selected" data-action="ban" data-value="${esc(b)}" ${hasActive()?'disabled':''}>${esc(b)} ×</button>`).join('')}</div></section>${weightUnitSettings()}${reliabilitySettings()}<section class="section"><h2>Finish sound</h2><p class="small">Plays at the 20-minute target; you can keep logging in overtime. Your device media volume also controls loudness. Keep the app open for reliable sound.</p><button data-action="toggle-sound" aria-pressed="${p.preferences?.sound!==false}">Sound ${p.preferences?.sound===false?'off':'on'}</button><div class="field"><label for="finish-sound">Sound</label><select id="finish-sound">${Object.entries(FINISH_SOUNDS).map(([key,tune])=>`<option value="${key}" ${finishSound()===key?'selected':''}>${tune.label}</option>`).join('')}</select></div><div class="field"><label for="finish-volume">Volume · <output id="finish-volume-value">${Math.round(finishVolume()*100)}%</output></label><input id="finish-volume" type="range" min="0" max="100" step="5" value="${Math.round(finishVolume()*100)}"></div><button data-action="test-sound" ${p.preferences?.sound===false?'disabled':''} style="margin-top:16px">Test finish sound</button></section></div>`;}
function modal(html){const m=document.querySelector('#modal');m.innerHTML=html;if(!m.open)m.showModal();}
function confirmReset(){modal('<h2>Reset this session?</h2><p>The timer and logged reps will be cleared. An unfinished session does not count toward your progress.</p><div class="builder-actions"><button data-action="close">Keep session</button><button class="primary" data-action="confirm-reset">Reset session</button></div>');}
async function setupAudio(){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();}catch{}}
function finish(s){
 if(!s||s.finished)return;if(s.running&&remaining(s)<=0&&!s.overtime)enterOvertime(s);if(!s.overtime)return;
 s.durationMs=workoutElapsed(s);s.overtimeMs=Math.max(0,s.durationMs-1200000);s.finished=true;s.running=false;s.remaining=0;
 const finishedAt=Date.now(),p=profile();
 if(!p.history.some(h=>h.id===s.id))p.history.push({id:s.id,date:localDate(new Date(finishedAt)),finishedAt,type:s.type,durationMs:s.durationMs,overtimeMs:s.overtimeMs,repEntries:sessionEntries(s),totalReps:countTotal(repEntries(s)),totalSeconds:countTotal(repEntries(s),'sec'),fingerprint:s.fingerprint||null,repLog:clone(s.repLog||[]),echoEligible:!s.echoInvalid});
 if(s.mode==='rotation'&&!s.rotationAdvanced){p.rotationIndex=(s.day+1)%p.schedule.length;s.rotationAdvanced=true;day=p.rotationIndex;}
 if(p.workoutOverrides?.slots)delete p.workoutOverrides.slots[s.day];persist();cancelFinishAudio();syncWakeLock();focusMode=false;render();
 modal(`<div class="celebrate"><div class="medal">✓</div><div class="eyebrow">WORKOUT SAVED</div><h2>Workout complete · ${countTotal(repEntries(s))} reps</h2><p>${durationCaption(s)} · overtime reps included.</p>${countTotal(repEntries(s),'sec')?`<p>+ ${countTotal(repEntries(s),'sec')} seconds of holds</p>`:''}${breakdown(sessionEntries(s))}<p>${esc(s.type)} circuit saved.<br><strong>${weeklyCompleted()} / ${weeklyTarget()} sessions this week · ${p.history.length} saved sessions</strong></p><button class="primary" data-action="view-progress">See my progress</button></div>`);
}

function tick(){
 const s=activeSession();if(s?.running&&!s.finished&&!s.overtime&&remaining(s)<=0){enterOvertime(s);return;}updateEcho();
 const el=document.querySelector('#timer');if(!el)return;const here=s&&s.day===day&&!s.finished,left=here?remaining(s):1200000,extra=here&&s.overtime;
 el.textContent=extra?'+'+clockText(workoutElapsed(s)-1200000):clockText(Math.ceil(left/1000)*1000);
 el.setAttribute('aria-label',extra?'Overtime elapsed':'Time remaining');
 document.querySelector('#timer-bar').style.width=(1-left/1200000)*100+'%';document.querySelector('.timer-dial').style.setProperty('--timer-angle',`${(1-left/1200000)*360}deg`);
 document.querySelector('.progress').setAttribute('aria-valuenow',String(Math.min(1200,Math.floor((1200000-left)/1000))));
 document.querySelector('#timer-status').textContent=here?(extra?(s.running?'Overtime · running':'Overtime · paused'):s.running?'Running':'Paused'):'Not started';
 document.querySelector('#start-btn').textContent=here?(s.running?'Pause':'Resume'):'Start workout';
 const label=document.querySelector('#clock-label');if(label)label.textContent=extra?'Overtime':'Time remaining';
}

function start(){
 let s=activeSession();if(isRotation()&&day!==nextWorkoutIndex()&&!hasActive())return;if(s&&!s.finished&&s.day!==day)return;
 if(!s||s.finished){const rows=currentCircuit();if(rows.length!==5||rows.some(r=>!r.main))return;s={id:crypto.randomUUID(),day,mode:profile().mode||'fixed',type:profile().schedule[day].type,circuit:clone(rows),repEntries:[],repLog:[],fingerprint:circuitFingerprint(rows),echoInvalid:false,remaining:1200000,running:false,finished:false,activeSlot:0,overtime:false,overtimeMs:0,milestoneNotified:false};profile().session=s;}
 if(s.running){if(remaining(s)<=0&&!s.overtime)enterOvertime(s);s.remaining=remaining(s);if(s.overtime)s.overtimeMs=Math.max(0,workoutElapsed(s)-1200000);s.running=false;}
 else{s.endAt=s.overtime?Date.now()-(s.overtimeMs||0):Date.now()+s.remaining;s.running=true;setupAudio().then(()=>{syncFinishAudio();paintRuntimeStatus();});}
 focusMode=profile().preferences?.compact!==false;persist();render();syncSessionRuntime();
}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,i=Number(b.dataset.i),p=profile(),s=activeSession();if(a==='test-sound'){setupAudio().then(()=>{playFinishTune();syncFinishAudio();paintRuntimeStatus();});return;}if(a==='setup'){openSetup();return;}if(a==='focus'){focusMode=!focusMode;render();return;}if(a==='echo-toggle'){p.echoOff=!p.echoOff;persist();render();return;}if(a==='tab'){tab=b.dataset.tab;openAlts.clear();render();}if(a==='day'){day=i;previewSwaps={};openAlts.clear();render();}if(a==='resume-view'){day=s.day;tab='Workout';render();}if(a==='next-workout'){day=nextWorkoutIndex();render();}if(a==='start')start();if(a==='reset')confirmReset();if(a==='close')document.querySelector('#modal').close();if(a==='confirm-reset'){cancelFinishAudio();focusMode=false;p.session=null;previewSwaps={};persist();document.querySelector('#modal').close();render();syncSessionRuntime();}if(a==='alt'){openExercisePicker(i);return;}if(a==='add-reps')addReps(i,Number(b.dataset.amount));if(a==='undo-reps')undoReps(i);if(a==='swap')swapExercise(i,Number(b.dataset.choice||0));if(a==='equipment'&&!hasActive()&&b.dataset.value!=='Bodyweight'){p.equipment=p.equipment.includes(b.dataset.value)?p.equipment.filter(x=>x!==b.dataset.value):[...p.equipment,b.dataset.value];previewSwaps={};p.workoutOverrides=null;persist();render();}if(a==='ban'&&!hasActive()){toggleBan(b.dataset.value);render();}if(a==='restore'&&!hasActive()){p.schedule[day].custom=null;p.workoutOverrides=null;persist();render();toast('Preset restored with your equipment filters.');}if(a==='view-progress'){document.querySelector('#modal').close();tab='Progress';render();}});
function toggleBan(value){const p=profile();p.bans=p.bans.includes(value)?p.bans.filter(x=>x!==value):[...p.bans,value];previewSwaps={};p.workoutOverrides=null;persist();}
document.addEventListener('change',e=>{if(e.target.id==='finish-sound'||e.target.id==='finish-volume'){const p=profile();p.preferences??={};if(e.target.id==='finish-sound')p.preferences.finishSound=e.target.value;else p.preferences.finishVolume=Math.max(0,Math.min(1,Number(e.target.value)/100));persist();syncFinishAudio();render();return;}if(e.target.id==='profile-select'){cancelFinishAudio();focusMode=false;state.active=e.target.value;setupDraft=null;if(tab==='Setup')tab='Workout';day=activeSession()&&!activeSession().finished?activeSession().day:defaultWorkoutIndex();previewSwaps={};persist();render();syncSessionRuntime();}if(e.target.id==='routine-type'&&!hasActive()){profile().schedule[day]={type:e.target.value,custom:null};profile().workoutOverrides=null;previewSwaps={};persist();render();}if(e.target.dataset.library!==undefined){const i=e.target.dataset.library,m=MOVES[e.target.value];if(!m)return;document.getElementById(`group-${i}`).value=m.group;for(const [field,value]of Object.entries({name:m.name,reps:m.reps,desc:m.description}))document.getElementById(`${field}-${i}`).value=value;for(const o of document.getElementById(`eq-${i}`).options)o.selected=m.equipment.includes(o.value);}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='profile-form'){cancelFinishAudio();focusMode=false;const name=f.get('name').trim();if(!name)return;const p=newProfile(name);state.profiles.push(p);state.active=p.id;day=defaultWorkoutIndex();persist();render();syncSessionRuntime();toast('New profile created.');}if(form.id==='rename-form'){const name=f.get('name').trim();if(name){profile().name=name;persist();render();toast('Profile renamed.');}}if(form.id==='ban-form'&&!hasActive()){const v=f.get('ban').trim();if(norm(v).replace(/^no /,'').length<2){toast('Enter a movement name.');return;}if(!profile().bans.includes(v))toggleBan(v);render();}if(form.id==='builder-form'&&!hasActive()){let rows=[];for(let i=0;i<5;i++){const main={name:f.get(`name-${i}`).trim(),reps:f.get(`reps-${i}`).trim(),description:f.get(`desc-${i}`).trim(),equipment:f.getAll(`eq-${i}`)};const altName=f.get(`alt-${i}`).trim();const alt=altName?{name:altName,reps:f.get(`altreps-${i}`).trim(),description:f.get(`altdesc-${i}`).trim(),equipment:f.getAll(`alteq-${i}`)}:null;if(!main.name||!main.reps||!main.equipment.length||(alt&&!alt.equipment.length)){toast('Each move needs a name, reps and equipment.');return;}if(!allowed(main)||(alt&&!allowed(alt))){toast(`Exercise ${i+1} conflicts with your equipment or exclusions.`);return;}if(/[+]/.test(main.name)||/\d\s*(extensions|raises).*\+|\+.*\d/.test(main.reps)){toast('Use one movement per slot. Log reps or seconds, not a combination.');return;}const known=Object.values(MOVES).find(m=>m.name===main.name);main.group=known?.group||f.get(`group-${i}`)||MOVES[PRESETS[profile().schedule[day].type][i][0]].group;if(!workoutGroups().includes(main.group)){toast('Choose a muscle group that belongs to this workout.');return;}main.pattern=known?.pattern||main.group;if(alt){const other=Object.values(MOVES).find(m=>m.name===alt.name);alt.group=other?.group||main.group;alt.pattern=other?.pattern||alt.group;if(alt.group!==main.group){toast('Choose an alternative from the same movement family.');return;}}rows.push({main,alt});}profile().schedule[day].custom=rows;profile().workoutOverrides=null;previewSwaps={};persist();tab='Workout';render();toast('Your five-exercise circuit is saved.');}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.profiles?.some(p=>p.id===next.active)){state=migrateState(validateState(next));mirrorState(JSON.stringify(state));day=hasActive()?activeSession().day:defaultWorkoutIndex();render();syncSessionRuntime();}}catch{}}});


document.addEventListener('click',e=>{
 const button=e.target.closest('[data-action="remember-workout"]');if(!button||button.disabled||hasActive())return;
 const rows=currentCircuit();if(rows.some(r=>!r.main)){toast('Choose an exercise for all five slots first.');return;}
 profile().schedule[day].custom=clone(rows);profile().workoutOverrides=null;persist();render();toast('Routine saved for future workouts.');
});

function challengeFor(m){
 if(!m)return null;const known=(m.id&&MOVES[m.id])||Object.values(MOVES).find(x=>x.name===m.name);
 return known?{level:known.challenge,loadDependent:known.loadDependent}:null;
}
function challengeBadge(m){const c=challengeFor(m);return c?`Level ${c.level}/5${c.loadDependent?'*':''}`:'Unrated';}
function workoutChallenge(rows){const levels=rows.map(r=>challengeFor(r.main)?.level).filter(Number.isFinite);if(!levels.length)return 'Custom challenge';const avg=levels.reduce((a,b)=>a+b,0)/levels.length;return `${avg<2?'Foundation':avg<3.5?'Moderate':'Demanding'} · reference level ${Math.round(avg)}/5`;}
function challengeRelation(main,alt){
 if(moveGroup(main)!==moveGroup(alt))return 'Different muscle group';const a=challengeFor(main),b=challengeFor(alt);if(!a||!b)return 'Unrated comparison';
 const diff=b.level-a.level;return diff===0?'Similar reference challenge':`${Math.abs(diff)>=2?'Much ':''}${diff>0?'harder':'lighter'} variant`;
}
function challengeDirection(main,alt){const a=challengeFor(main),b=challengeFor(alt);return !a||!b?'unrated':b.level<a.level?'lighter':b.level>a.level?'harder':'similar';}
function challengeInfo(){modal(`<h2 id="picker-title">What do exercise levels mean?</h2><p>Level 1 is a simpler reference variant; level 5 is a highly demanding variant. Compare within the same muscle group. A different movement pattern also changes the training stimulus.</p><p>For example: kneeling push-ups 1/5, standard push-ups 3/5, barbell bench press 4/5 at a typical working load.</p><p><strong>* Loaded exercise:</strong> the actual challenge depends on your weight, technique, range of motion and strength. A lightly loaded bench press can be easier than a push-up. These are reference ratings, not measured effort, strength, calories or muscle-growth scores.</p><p>Custom exercises stay unrated. Workout level summarizes the selected reference levels, not your personal fitness.</p><button data-action="close">Got it</button>`);}
let pickerSlot=null;
function openExercisePicker(i){
 const rows=currentCircuit(),r=rows[i];if(!r)return;pickerSlot=i;const m=reviewedMovement(r.main),group=slotGroup(i,r),choices=alternativesFor(r,i,rows),total=libraryForGroup(group).length;
 modal(`<section class="exercise-picker" aria-labelledby="picker-title"><div class="picker-top"><div><span class="eyebrow">${esc(MUSCLE_GROUPS[group]||'Exercises')}</span><h2 id="picker-title">Choose your exercise</h2></div><button data-action="close" aria-label="Close exercise picker">✕</button></div>${m?`<div class="picker-current"><span class="small muted">CURRENT EXERCISE</span><strong>${esc(m.name)} <span class="challenge-badge">${challengeBadge(m)}</span></strong><p class="small muted">${esc(m.pattern||movePattern(m))} · ${esc(equipmentCaption(m))}</p><p class="counting-help">${esc(countingHint(m))}</p><details><summary>Form & load</summary>${movementGuide(m)}${loadField(m,i,activeSession())}</details></div>`:''}<p class="small muted">${choices.length} available alternatives · ${total} exercises in this group. Equipment, exclusions and occupied slots are filtered.</p>${group==='squat'?'<p class="leg-slot-note small muted">This slot targets quads and knee-dominant leg work. Step-ups, wall sits and leg extensions are also available when your equipment matches. Holds use seconds; leg extensions isolate the quads and are a different stimulus from squats or lunges.</p>':''}<div class="picker-search"><label for="search-${i}">Search exercises</label><input type="search" id="search-${i}" data-exercise-search="${i}" placeholder="Name, equipment or movement pattern" autocomplete="off"><label for="level-filter">Challenge compared with current</label><select id="level-filter" data-level-filter="${i}"><option value="all">All challenge levels</option><option value="lighter">Lighter variants</option><option value="similar">Similar reference challenge</option><option value="harder">Harder variants</option></select></div><p class="small muted" role="status" data-search-count="${i}">${choices.length} options</p><div class="picker-results">${choices.map(alt=>`<article class="alternative-option" data-exercise-option="${i}" data-direction="${challengeDirection(m,alt)}" data-search="${esc(norm(alt.name+' '+alt.equipment.join(' ')+' '+alt.pattern+' '+groupLabel(alt)))}"><div><div class="option-level"><span class="challenge-badge">${challengeBadge(alt)}</span><strong class="challenge-${challengeDirection(m,alt)}">${esc(challengeRelation(m,alt))}</strong></div><h3>${esc(alt.name)}</h3><p class="small muted">${esc(groupLabel(alt))} · ${esc(alt.reps)}</p><p class="counting-help">${esc(countingHint(alt))}</p><p class="small muted">${esc(equipmentCaption(alt))}</p><span class="swap-kind">${esc(alt.pattern)} · ${esc(swapRelation(m,alt))}</span><details><summary>Execution tips</summary><p class="small muted">${esc(alt.description)}</p></details></div><button data-action="picker-swap" data-i="${i}" data-name="${esc(alt.name)}" aria-label="Choose ${esc(alt.name)}">Choose</button></article>`).join('')}</div><p class="small muted" data-search-empty="${i}" ${choices.length?'hidden':''}>No matching exercises. Try another search or adjust equipment and exclusions in Settings.</p><div class="picker-bottom"><button class="text-button" data-action="challenge-info">* About reference levels</button><p class="small muted">A loaded exercise depends on the weight you use. Changing movement pattern changes the stimulus too.</p><button data-action="remember-workout" ${hasActive()?'disabled':''}>Save current choices as my routine</button><p class="small muted">Choose updates this workout. Saving retains all five choices for future workouts; finish or reset an active session first.</p></div></section>`);
 document.querySelector('#modal').setAttribute('aria-label','Exercise choices');
}
function filterPicker(i){
 const search=document.querySelector(`#search-${i}`),filter=document.querySelector('[data-level-filter]');
 const terms=norm(search?.value||'').split(' ').filter(Boolean);let visible=0;
 for(const node of document.querySelectorAll(`[data-exercise-option="${i}"]`)){
  node.hidden=!terms.every(term=>node.dataset.search.includes(term))||(filter?.value&&filter.value!=='all'&&node.dataset.direction!==filter.value);if(!node.hidden)visible++;
 }
 document.querySelector(`[data-search-count="${i}"]`).textContent=`${visible} options`;
 document.querySelector(`[data-search-empty="${i}"]`).hidden=visible>0;
}
document.addEventListener('input',e=>{if(e.target.dataset.exerciseSearch!==undefined)filterPicker(e.target.dataset.exerciseSearch);});
document.addEventListener('change',e=>{if(e.target.id==='finish-sound'||e.target.id==='finish-volume'){const p=profile();p.preferences??={};if(e.target.id==='finish-sound')p.preferences.finishSound=e.target.value;else p.preferences.finishVolume=Math.max(0,Math.min(1,Number(e.target.value)/100));persist();syncFinishAudio();render();return;}if(e.target.dataset.levelFilter!==undefined)filterPicker(e.target.dataset.levelFilter);});
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,i=Number(b.dataset.i);
 if(a==='challenge-info')challengeInfo();
 if(a==='picker-swap'){
  const choices=alternativesFor(currentCircuit()[i],i),index=choices.findIndex(m=>m.name===b.dataset.name);if(index<0){toast('This choice is no longer available.');return;}
  const s=activeSession();if(s?.running&&remaining(s)<=0)enterOvertime(s);swapExercise(i,index);openExercisePicker(i);
 }
 if(a==='repeat-set'){
  const s=activeSession();if(!s||s.finished||s.day!==day)return;if(s.running&&remaining(s)<=0)enterOvertime(s);
  const m=currentCircuit()[i]?.main,last=previousSet(m,s);if(!last)return;
  saveLoad(i,last.weightKg==null?'':String(last.weightKg));addReps(i,last.amount);
 }
 if(a==='remember-workout'&&!hasActive())document.querySelector('#modal').close();
 if(a==='close'&&pickerSlot!==null){document.querySelector(`[data-action="alt"][data-i="${pickerSlot}"]`)?.focus?.();pickerSlot=null;}
});

document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;
 if(b.dataset.action==='finish-workout')finish(activeSession());
 if(b.dataset.action==='workout-guide')showWorkoutGuide();
});

const WORKOUT_GUIDES={
 Push:{goal:'Train your chest, shoulders and triceps through pressing and controlled shoulder work.',pace:'This circuit has two chest slots, two shoulder slots and one triceps slot. Do one set in the listed order; the second chest movement can use a lighter load or variant. Rest as needed instead of rushing repeated presses.',slots:['Chest press','Shoulder press','Second chest movement','Shoulder accessory','Triceps']},
 Pull:{goal:'Train your back and biceps, with core work to support a stable trunk.',pace:'Keep your torso steady in rows and pulls. Complete both sides of one-arm movements before moving on.',slots:['Row','Pulldown / back control','Upper-back accessory','Biceps','Core']},
 Lower:{goal:'Train your legs, hamstrings, glutes, hips and calves.',pace:'Choose knee-dominant leg work such as a squat, lunge or step-up; a wall sit is a timed option. In hinges, move from the hips. Keep the hip accessories controlled rather than chasing speed.',slots:['Quads / knee-dominant legs','Hip hinge / hamstrings','Glutes','Hip control','Calves']},
 'Full Body':{goal:'Cover legs, pushing, pulling, the back of your legs and core in one session.',pace:'The different muscle groups let you move around the circuit without rushing. A little rest between exercises is normal.',slots:['Legs','Chest / pushing','Back / pulling','Hip hinge','Core']},
 Upper:{goal:'Train pushing and pulling muscles across your upper body.',pace:'Keep rows and presses controlled, then use lighter loads for the arm accessories.',slots:['Back','Chest','Upper-back accessory','Biceps','Triceps']},
 Conditioning:{goal:'Practice a steady full-body circuit with manageable breathing and controlled movement.',pace:'Choose a pace you can sustain while maintaining technique. Rest until breathing is comfortable before restarting.',slots:['Full body','Full body','Legs','Pushing','Core']}
};
function showWorkoutGuide(){
 const type=profile().schedule[day].type,guide=WORKOUT_GUIDES[type]||WORKOUT_GUIDES[type==='Legs'?'Lower':'Full Body'],rows=currentCircuit().map(r=>({...r,main:reviewedMovement(r.main)}));
 modal(`<section class="workout-instructions"><div class="picker-top"><h2>${esc(type)} · how to train</h2><button data-action="close" aria-label="Close workout instructions">✕</button></div><p>${esc(guide.goal)}</p><h3>Before you start</h3><p>Warm up for 3–5 minutes outside the timer: easy walking or marching, comfortable joint movements, and a light practice set of your first exercise. Clear your space and check equipment and anchors.</p><h3>Your 20-minute circuit</h3><ol><li>Start the timer. Do <strong>one set of exercise 1</strong> using its suggested reps or hold time.</li><li>Log the set with +1, +5 or +10. Complete exercises 2–5 in the same way, then go back to exercise 1.</li><li>Rest when you need it — around 30–60 seconds is a useful starting point, longer if needed. The clock continues; use Pause for an interruption.</li><li>Use a manageable weight. Finish most sets feeling you could do another 2–3 controlled reps. This is not a race or a maximum-rep test.</li></ol><p>${esc(guide.pace)}</p><h3>Your selected exercises</h3><ol class="guide-exercise-list">${rows.map((r,i)=>`<li><strong>${esc(r.main?.name||'Choose an exercise')}</strong><p class="small muted">${esc(r.main?groupLabel(r.main):guide.slots[i])} · ${esc(r.main?.reps||'No target')} · ${challengeBadge(r.main)}</p><p>${esc(r.main?.description||'Adjust your filters before starting.')}</p><p class="counting-help">${esc(countingHint(r.main))}</p></li>`).join('')}</ol><h3>Counting correctly</h3><p>For “8 / side”, do 8 left and 8 right, then log <strong>16 total reps</strong>. For timed holds, log seconds, never reps. “Repeat last set” adds the last recorded amount and restores its load; Undo removes your most recent entry for that slot.</p><h3>At 20 minutes</h3><p>The chime marks your target. The timer switches to <strong>Overtime (+00:00)</strong>; your workout stays open. Finish your last set, add any remaining reps, then tap <strong>Finish & save</strong>. The next workout advances only after saving. You do not need to train longer just to raise the overtime number.</p><p class="small muted">Stop if you feel pain, dizziness or unusual discomfort. The chime requires enabled sound and browser support; a closed or suspended browser cannot guarantee an alarm. Opening this guide does not pause the clock.</p><button class="primary" data-action="close">Got it</button></section>`);
 document.querySelector('#modal').setAttribute('aria-label',type+' workout instructions');
}

function countingHint(m){
 if(!m)return '';
 const target=m.reps||'';
 if(unitFor(m)==='sec')return /\/\s*side/i.test(target)?'Hold on each side; log both sides’ seconds together.':'Log seconds held, not reps.';
 if(/load side/i.test(target))return 'March with the weight on each side; count each knee lift once and log all steps together.';
 if(/direction.*side/i.test(target))return 'Complete both directions on both sides. One full circle is one rep; log all circles together.';
 if(/direction/i.test(target))return 'Complete both directions. One full circle is one rep; log both directions together.';
 if(/steps?\s*\/\s*side/i.test(target))return 'Complete the target in each direction. Count each step once and log all steps together.';
 if(/\/\s*side/i.test(target))return 'Complete the target on each side; log left and right together (8 + 8 = 16 reps).';
 if(/alternating|steps/i.test(target))return 'The target is the combined total across both sides; do not double it.';
 return 'One complete movement is one rep; log the total you complete.';
}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action="kettlebell-count"]');if(!b||b.disabled||hasActive())return;const n=Number(b.dataset.value);if(![1,2].includes(n))return;profile().kettlebellCount=n;profile().workoutOverrides=null;persist();render();});

document.addEventListener('click',e=>{const b=e.target.closest('[data-action="dumbbell-count"]');if(!b||b.disabled||hasActive())return;const n=Number(b.dataset.value);if(![1,2].includes(n))return;profile().dumbbellCount=n;profile().workoutOverrides=null;persist();render();});

function showAboutApp(){modal(`<h2>About Daily Reps</h2><p>20-minute circuits with your own equipment, exercise choices and rep tracking. The interface is in English.</p><h3>Your data</h3><p>Your workout plan, equipment choices, excluded exercises, weights and training history are saved locally in this browser, including a local recovery copy. There is no account or automatic synchronization to other devices.</p><p>Use Export backup to keep a file, and Import backup to move it to another browser or device. Clearing website data can remove your training history. Import previews the backup before replacing local data.</p><p>The app includes no advertising or analytics SDK. GitHub Pages hosts the website; the hosting provider may process request information. Your saved workout records are not automatically uploaded by this app.</p><p>You can export or delete your local data in Settings. The twenty-minute sound needs browser audio permission; a closed or suspended browser cannot guarantee an alarm.</p><p><a href="https://github.com/frap-coder/Workout" target="_blank" rel="noopener">Project source and issue tracker</a></p><button class="primary" data-action="close">Close</button>`);document.querySelector('#modal').setAttribute('aria-label','About Daily Reps and local data');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="about-app"]');if(b&&!b.disabled)showAboutApp();});
document.addEventListener('change',e=>{if(e.target.id==='finish-sound'||e.target.id==='finish-volume'){const p=profile();p.preferences??={};if(e.target.id==='finish-sound')p.preferences.finishSound=e.target.value;else p.preferences.finishVolume=Math.max(0,Math.min(1,Number(e.target.value)/100));persist();syncFinishAudio();render();return;}if(e.target.id==='weight-unit'&&['kg','lb'].includes(e.target.value)){profile().preferences??={};profile().preferences.weightUnit=e.target.value;persist();render();}});

document.addEventListener('input',e=>{if(e.target.id==='finish-volume')document.getElementById('finish-volume-value').textContent=e.target.value+'%';});
